import json
import subprocess
js = "const assert = require('node:assert/strict');
const { QueryClient, dehydrate, hydrate } = require('/opt/query-core.cjs');
(async () => {
  const originalNow = Date.now;
  let now = 1700000000000;
  Date.now = () => now;
  const initialTime = now;
  const server = new QueryClient({defaultOptions: {queries: {gcTime: Infinity}}});
  try {
    await server.fetchQuery({queryKey: ['report'], staleTime: 300000, queryFn: async () => 'server-data'});
    const payload = JSON.parse(JSON.stringify(dehydrate(server)));
    assert.equal(payload.queries.length, 1);
    const dehydrated = payload.queries[0];
    assert.equal(dehydrated.state.dataUpdatedAt, initialTime);
    assert.equal(dehydrated.state.isInvalidated, false);
    assert.equal(dehydrated.state.status, 'success');
    assert.equal('staleTime' in dehydrated, false);
    assert.equal('staleTime' in dehydrated.state, false);
    assert.equal('queryFn' in dehydrated, false);
    const rows = [];
    for (const age of [10000, 299999, 300000, 300001]) {
      now = initialTime + age;
      const client = new QueryClient({defaultOptions: {queries: {staleTime: 5000, gcTime: Infinity}}});
      try {
        hydrate(client, payload);
        const query = client.getQueryCache().find({queryKey: ['report']});
        assert.equal(query.getObserversCount(), 0);
        assert.equal(query.state.isInvalidated, false);
        assert.equal(query.options.staleTime, 5000);
        assert.equal(query.state.fetchStatus, 'idle');
        const mergedStaleTime = client.defaultQueryOptions({queryKey: ['report'], staleTime: 300000}).staleTime;
        assert.equal(mergedStaleTime, 300000);
        const before = {storedStaleTime: query.options.staleTime, isStale: query.isStale(), isStaleByTime: query.isStaleByTime(300000)};
        let calls = 0;
        const value = await client.fetchQuery({queryKey: ['report'], staleTime: 300000, queryFn: async () => {calls++; return 'client-data';}});
        assert.equal(calls, age >= 300000 ? 1 : 0);
        assert.equal(value, age >= 300000 ? 'client-data' : 'server-data');
        rows.push({age, calls, value, ...before});
      } finally {client.clear();}
    }
    console.log(JSON.stringify({dataUpdatedAt: dehydrated.state.dataUpdatedAt, payloadKeys: Object.keys(dehydrated).sort(), rows}));
  } finally {server.clear(); Date.now = originalNow;}
})().catch(error => {console.error(error); process.exitCode = 1;});
"
result = subprocess.run(["node", "-"], input=js, text=True, capture_output=True, timeout=20, check=True)
